/*
 * 1:1 port of opencode's Divider (`@opencode/ui`, MIT):
 * packages/ui/src/layout/divider/divider.css (`divider-v2`).
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream: the 1px line, its 0.5px transform and its strong border colour:
 *
 *   [data-component="divider-v2"]  →  [data-slot="separator"]  (ui-sdk's root slot)
 *
 * Upstream's Divider is horizontal only; it hardcodes `aria-orientation`.
 * ui-sdk supports both orientations, so the vertical rule mirrors upstream's
 * values onto the other axis (width 1px, scaleX(0.5), no fixed height, so
 * `align-self: stretch` makes it take the row's height). That one rule is the
 * only Kitsaas addition.
 *
 * Upstream has no [data-color-scheme="dark"] block; --v2-border-border-strong
 * flips with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="separator"] {
    box-sizing: border-box;
    width: 100%;
    height: 1px;
    transform: scaleY(0.5);
    border: none;
    background: var(--v2-border-border-strong);
    flex: none;
    align-self: stretch;
    flex-grow: 0;
  }

  [data-slot="separator"][data-orientation="vertical"] {
    width: 1px;
    height: auto;
    transform: scaleX(0.5);
  }
}
